var builder=WebApplication.CreateBuilder(args);var secret=builder.Configuration["JWT_SECRET"]??throw new Exception("JWT_SECRET required");if(secret.Length<32)throw new Exception("JWT_SECRET too short");builder.Services.AddDbContext<BookingDb>(o=>o.UseNpgsql(builder.Configuration.GetConnectionString("Db")??throw new Exception("Database required")));builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new(){ValidateIssuer=true,ValidIssuer="bookflow",ValidateAudience=true,ValidAudience="bookflow",ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secret)),ValidateLifetime=true});builder.Services.AddAuthorization();builder.Services.AddHttpClient();builder.Services.AddHostedService<Reminders>();builder.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.WithOrigins(builder.Configuration["WEB_ORIGIN"]??"http://localhost:3000").AllowAnyHeader().AllowAnyMethod()));var app=builder.Build();if(args.Contains("--migrate")){using var scope=app.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<BookingDb>();await db.Database.MigrateAsync();if(builder.Configuration.GetValue<bool>("DEMO_MODE")&&!await db.Tenants.AnyAsync()){var t=new Tenant{Name="Салон Неон",Slug="neon"};db.Tenants.Add(t);var branch=new Branch{TenantId=t.Id,Name="Центр",Address="Невский, 1"};db.Branches.Add(branch);var employee=new Employee{TenantId=t.Id,BranchId=branch.Id,Name="Анна"};db.Employees.Add(employee);db.Services.Add(new Service{TenantId=t.Id,Name="Стрижка",Price=1900,DurationMinutes=60});var demoCustomer=new Customer{TenantId=t.Id,Name="Первый клиент"};db.Customers.Add(demoCustomer);db.Appointments.Add(new Appointment{TenantId=t.Id,EmployeeId=employee.Id,ServiceId=db.Services.Local.Single().Id,CustomerId=demoCustomer.Id,Starts=DateTime.UtcNow.Date.AddDays(1).AddHours(11),Ends=DateTime.UtcNow.Date.AddDays(1).AddHours(12),Price=1900,Status="confirmed"});foreach(var day in Enum.GetValues<DayOfWeek>())if(day!=DayOfWeek.Sunday)db.Shifts.Add(new Shift{TenantId=t.Id,EmployeeId=employee.Id,Day=day,Starts=new TimeOnly(10,0),Ends=new TimeOnly(19,0)});var email=builder.Configuration["DEMO_EMAIL"]??throw new Exception("DEMO_EMAIL required");var password=builder.Configuration["DEMO_PASSWORD"]??throw new Exception("DEMO_PASSWORD required");db.Members.Add(new Member{TenantId=t.Id,Email=email,Name="Владелец",PasswordHash=Convert.ToBase64String(Rfc2898DeriveBytes.Pbkdf2(password,Encoding.UTF8.GetBytes(email),210000,HashAlgorithmName.SHA256,32))});await db.SaveChangesAsync();}return;}app.UseCors();app.UseAuthentication();app.UseAuthorization();app.Use(async(c,next)=>{try{await next();}catch(InvalidOperationException ex){c.Response.StatusCode=400;await c.Response.WriteAsJsonAsync(new{error=ex.Message});}catch(DbUpdateException){c.Response.StatusCode=409;await c.Response.WriteAsJsonAsync(new{error="Конфликт данных"});}catch(Npgsql.PostgresException ex)when(ex.SqlState=="40001"){c.Response.StatusCode=409;await c.Response.WriteAsJsonAsync(new{error="Слот занят, обновите расписание"});}});
string Token(Guid tenant,string role,string id)=>new JwtSecurityTokenHandler().WriteToken(new JwtSecurityToken("bookflow","bookflow",[new Claim("tenant",tenant.ToString()),new Claim(ClaimTypes.Role,role),new Claim(ClaimTypes.NameIdentifier,id)],expires:DateTime.UtcNow.AddHours(8),signingCredentials:new(new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secret)),SecurityAlgorithms.HmacSha256)));
bool Staff(ClaimsPrincipal u)=>u.IsInRole("Owner")||u.IsInRole("Admin")||u.IsInRole("Employee");
app.MapPost("/api/auth/register",async(Register x,BookingDb db)=>{if(x.Password.Length<12||x.Email.Length>254||x.Organization.Length is <2 or >120||x.Slug.Length is <3 or >40||!x.Slug.All(c=>char.IsAsciiLetterOrDigit(c)||c=='-'))return Results.BadRequest(new{error="Проверьте данные: пароль от 12 символов, slug 3–40 символов"});if(await db.Members.AnyAsync(y=>y.Email==x.Email)||await db.Tenants.AnyAsync(y=>y.Slug==x.Slug))return Results.Conflict();var tenant=new Tenant{Name=x.Organization,Slug=x.Slug};db.Tenants.Add(tenant);var owner=new Member{TenantId=tenant.Id,Email=x.Email,Name=x.Email,PasswordHash=Convert.ToBase64String(Rfc2898DeriveBytes.Pbkdf2(x.Password,Encoding.UTF8.GetBytes(x.Email),210000,HashAlgorithmName.SHA256,32))};db.Members.Add(owner);await db.SaveChangesAsync();return Results.Ok(new{token=Token(tenant.Id,owner.Role,owner.Id.ToString()),tenantId=tenant.Id});});
app.MapPost("/api/auth/login",async(Login x,BookingDb db)=>{var m=await db.Members.SingleOrDefaultAsync(y=>y.Email==x.Email);if(m==null||!CryptographicOperations.FixedTimeEquals(Convert.FromBase64String(m.PasswordHash),Rfc2898DeriveBytes.Pbkdf2(x.Password,Encoding.UTF8.GetBytes(m.Email),210000,HashAlgorithmName.SHA256,32)))return Results.Unauthorized();return Results.Ok(new{token=Token(m.TenantId,m.Role,m.Id.ToString()),role=m.Role,tenantId=m.TenantId});});
app.MapPost("/api/auth/telegram",async(TelegramAuth x,BookingDb db)=>{var t=await db.Tenants.SingleOrDefaultAsync(y=>y.Slug==x.Tenant);if(t is null)return Results.NotFound();var token=builder.Configuration["TELEGRAM_BOT_TOKEN"];if(string.IsNullOrEmpty(token))return Results.Unauthorized();var fields=x.InitData.Split('&').Select(y=>y.Split('=',2)).Where(y=>y.Length==2).ToDictionary(y=>Uri.UnescapeDataString(y[0]),y=>Uri.UnescapeDataString(y[1]));if(!fields.Remove("hash",out var hash)||!fields.TryGetValue("auth_date",out var date)||!long.TryParse(date,out var stamp)||Math.Abs(DateTimeOffset.UtcNow.ToUnixTimeSeconds()-stamp)>3600||hash.Length!=64||!hash.All(Uri.IsHexDigit))return Results.Unauthorized();var check=string.Join('\n',fields.OrderBy(y=>y.Key,StringComparer.Ordinal).Select(y=>$"{y.Key}={y.Value}"));var h=HMACSHA256.HashData(HMACSHA256.HashData(Encoding.UTF8.GetBytes("WebAppData"),Encoding.UTF8.GetBytes(token)),Encoding.UTF8.GetBytes(check));if(!CryptographicOperations.FixedTimeEquals(h,Convert.FromHexString(hash)))return Results.Unauthorized();using var json=JsonDocument.Parse(fields["user"]);var id=json.RootElement.GetProperty("id").GetInt64();var customer=await db.Customers.SingleOrDefaultAsync(y=>y.TenantId==t.Id&&y.TelegramId==id);if(customer==null){customer=new Customer{TenantId=t.Id,TelegramId=id,Name=json.RootElement.GetProperty("first_name").GetString()??"Клиент"};db.Customers.Add(customer);await db.SaveChangesAsync();}return Results.Ok(new{token=Token(t.Id,"Customer",customer.Id.ToString()),role="Customer",tenantId=t.Id});});
var api=app.MapGroup("/api").RequireAuthorization();
api.MapGet("/members",(ClaimsPrincipal u,BookingDb db)=>db.Members.Where(x=>x.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)).Select(x=>new{x.Id,x.Email,x.Name,x.Role}));
api.MapPost("/members",async(MemberInput x,ClaimsPrincipal u,BookingDb db)=>{if(!u.IsInRole("Owner"))return Results.Forbid();if(!new[]{"Admin","Employee"}.Contains(x.Role)||x.Password.Length<12||x.Email.Length>254)return Results.BadRequest();if(await db.Members.AnyAsync(y=>y.Email==x.Email))return Results.Conflict();var m=new Member{TenantId=Guid.Parse(u.FindFirstValue("tenant")!),Email=x.Email,Name=x.Name,Role=x.Role,PasswordHash=Convert.ToBase64String(Rfc2898DeriveBytes.Pbkdf2(x.Password,Encoding.UTF8.GetBytes(x.Email),210000,HashAlgorithmName.SHA256,32))};db.Members.Add(m);await db.SaveChangesAsync();return Results.Ok(new{m.Id,m.Email,m.Name,m.Role});});
api.MapGet("/tenants/me",async(ClaimsPrincipal u,BookingDb db)=>await db.Tenants.Where(x=>x.Id==Guid.Parse(u.FindFirstValue("tenant")!)).Select(x=>new{x.Id,x.Name,x.Slug}).SingleAsync());
api.MapPut("/tenants/me",async(ClaimsPrincipal u,BookingDb db,TenantInput x)=>{if(!u.IsInRole("Owner"))return Results.Forbid();var t=await db.Tenants.SingleAsync(y=>y.Id==Guid.Parse(u.FindFirstValue("tenant")!));t.Name=x.Name;await db.SaveChangesAsync();return Results.Ok(t);});
api.MapGet("/branches",(ClaimsPrincipal u,BookingDb db)=>db.Branches.Where(x=>x.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)).OrderBy(x=>x.Name));
api.MapPost("/branches",async(ClaimsPrincipal u,BookingDb db,BranchInput x)=>{if(!u.IsInRole("Owner")&&!u.IsInRole("Admin"))return Results.Forbid();var b=new Branch{TenantId=Guid.Parse(u.FindFirstValue("tenant")!),Name=x.Name,Address=x.Address};db.Branches.Add(b);await db.SaveChangesAsync();return Results.Ok(b);});
api.MapGet("/services",(ClaimsPrincipal u,BookingDb db)=>db.Services.Where(x=>x.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)).OrderBy(x=>x.Name));
api.MapPost("/services",async(ClaimsPrincipal u,BookingDb db,ServiceInput x)=>{if(!Staff(u)||x.Price<0||x.DurationMinutes<15||x.DurationMinutes>480)return Results.BadRequest();var s=new Service{TenantId=Guid.Parse(u.FindFirstValue("tenant")!),Name=x.Name,Price=x.Price,DurationMinutes=x.DurationMinutes};db.Services.Add(s);await db.SaveChangesAsync();return Results.Ok(s);});
api.MapPut("/services/{id:guid}",async(Guid id,ClaimsPrincipal u,BookingDb db,ServiceInput x)=>{if(!Staff(u))return Results.Forbid();var s=await db.Services.SingleOrDefaultAsync(y=>y.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)&&y.Id==id);if(s==null)return Results.NotFound();s.Name=x.Name;s.Price=x.Price;s.DurationMinutes=x.DurationMinutes;await db.SaveChangesAsync();return Results.Ok(s);});
api.MapGet("/employees",(ClaimsPrincipal u,BookingDb db)=>db.Employees.Where(x=>x.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)).OrderBy(x=>x.Name));
api.MapPost("/employees",async(ClaimsPrincipal u,BookingDb db,EmployeeInput x)=>{if(!Staff(u)||!await db.Branches.AnyAsync(y=>y.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)&&y.Id==x.BranchId))return Results.BadRequest();var e=new Employee{TenantId=Guid.Parse(u.FindFirstValue("tenant")!),BranchId=x.BranchId,Name=x.Name};db.Employees.Add(e);await db.SaveChangesAsync();return Results.Ok(e);});
api.MapGet("/schedules/{employee:guid}",(Guid employee,ClaimsPrincipal u,BookingDb db)=>db.Shifts.Where(x=>x.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)&&x.EmployeeId==employee));
api.MapPut("/schedules/{employee:guid}",async(Guid employee,ClaimsPrincipal u,BookingDb db,ShiftInput x)=>{if(!Staff(u)||x.Starts>=x.Ends||!await db.Employees.AnyAsync(y=>y.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)&&y.Id==employee))return Results.BadRequest();var s=await db.Shifts.SingleOrDefaultAsync(y=>y.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)&&y.EmployeeId==employee&&y.Day==x.Day);if(s==null){s=new Shift{TenantId=Guid.Parse(u.FindFirstValue("tenant")!),EmployeeId=employee,Day=x.Day};db.Shifts.Add(s);}s.Starts=x.Starts;s.Ends=x.Ends;s.DayOff=x.DayOff;await db.SaveChangesAsync();return Results.Ok(s);});
api.MapPost("/leaves",async(LeaveInput x,ClaimsPrincipal u,BookingDb db)=>{if(!Staff(u)||x.Starts>=x.Ends||!await db.Employees.AnyAsync(y=>y.Id==x.EmployeeId&&y.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)))return Results.BadRequest();var leave=new Leave{TenantId=Guid.Parse(u.FindFirstValue("tenant")!),EmployeeId=x.EmployeeId,Starts=x.Starts,Ends=x.Ends};db.Leaves.Add(leave);await db.SaveChangesAsync();return Results.Ok(leave);});
async Task<List<DateTime>> Slots(BookingDb db,Guid tenant,Guid employee,Service service,DateOnly day,Guid? excludeId=null){if(day<DateOnly.FromDateTime(DateTime.UtcNow)||day> DateOnly.FromDateTime(DateTime.UtcNow.AddDays(60)))return [];var shift=await db.Shifts.SingleOrDefaultAsync(x=>x.TenantId==tenant&&x.EmployeeId==employee&&x.Day==day.DayOfWeek);if(shift==null||shift.DayOff)return [];var start=day.ToDateTime(shift.Starts,DateTimeKind.Utc);var end=day.ToDateTime(shift.Ends,DateTimeKind.Utc);var busy=await db.Appointments.Where(x=>x.TenantId==tenant&&x.EmployeeId==employee&&x.Starts<end&&x.Ends>start&&x.Status!="cancelled"&&x.Id!=excludeId).Select(x=>new{x.Starts,x.Ends}).ToListAsync();var leaves=await db.Leaves.Where(x=>x.TenantId==tenant&&x.EmployeeId==employee&&x.Starts<end&&x.Ends>start).ToListAsync();var times=new List<DateTime>();for(var current=start;current.AddMinutes(service.DurationMinutes)<=end;current=current.AddMinutes(15))if(current>DateTime.UtcNow.AddMinutes(15)&&!busy.Any(x=>x.Starts<current.AddMinutes(service.DurationMinutes)&&x.Ends>current)&&!leaves.Any(x=>x.Starts<current.AddMinutes(service.DurationMinutes)&&x.Ends>current))times.Add(current);return times;}
api.MapGet("/availability",async(Guid employee,Guid service,DateOnly date,ClaimsPrincipal u,BookingDb db)=>{var s=await db.Services.SingleOrDefaultAsync(x=>x.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)&&x.Id==service&&x.Active);return s is null?Results.NotFound():Results.Ok(await Slots(db,Guid.Parse(u.FindFirstValue("tenant")!),employee,s,date));});
api.MapGet("/appointments",(ClaimsPrincipal u,BookingDb db,int? page)=>db.Appointments.Where(x=>x.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)&&(!u.IsInRole("Customer")||x.CustomerId==Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!))).OrderByDescending(x=>x.Starts).Skip((Math.Clamp(page??1,1,10000)-1)*50).Take(50));
api.MapPost("/appointments",async(BookingInput x,ClaimsPrincipal u,BookingDb db,IHttpClientFactory clients)=>{var tenant=Guid.Parse(u.FindFirstValue("tenant")!);var s=await db.Services.SingleOrDefaultAsync(y=>y.Id==x.ServiceId&&y.TenantId==tenant&&y.Active);if(s==null||!await db.Employees.AnyAsync(y=>y.Id==x.EmployeeId&&y.TenantId==tenant&&y.Active))return Results.BadRequest();var customer=u.IsInRole("Customer")?Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!):x.CustomerId;if(!await db.Customers.AnyAsync(y=>y.Id==customer&&y.TenantId==tenant))return Results.BadRequest();await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);if(!(await Slots(db,tenant,x.EmployeeId,s,DateOnly.FromDateTime(x.Starts))).Contains(x.Starts))return Results.Conflict(new{error="Слот занят"});var a=new Appointment{TenantId=tenant,EmployeeId=x.EmployeeId,ServiceId=s.Id,CustomerId=customer,Starts=x.Starts,Ends=x.Starts.AddMinutes(s.DurationMinutes),Price=s.Price};db.Appointments.Add(a);await db.SaveChangesAsync();await tx.CommitAsync();var bot=builder.Configuration["TELEGRAM_BOT_TOKEN"];var recipient=await db.Customers.SingleAsync(y=>y.Id==customer);if(recipient.TelegramId.HasValue&&!string.IsNullOrWhiteSpace(bot)&&!builder.Configuration.GetValue<bool>("DEMO_MODE")){try{await clients.CreateClient().PostAsJsonAsync($"https://api.telegram.org/bot{bot}/sendMessage",new{chat_id=recipient.TelegramId.Value,text=$"Запись подтверждена: {a.Starts:dd.MM HH:mm} UTC"});}catch(Exception ex){app.Logger.LogError(ex,"Уведомление о записи {Id} не отправлено",a.Id);}}return Results.Ok(a);});
api.MapPost("/appointments/{id:guid}/reschedule",async(Guid id,RescheduleInput x,ClaimsPrincipal u,BookingDb db)=>{var tenant=Guid.Parse(u.FindFirstValue("tenant")!);await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var a=await db.Appointments.SingleOrDefaultAsync(y=>y.Id==id&&y.TenantId==tenant&&y.Status!="cancelled");if(a==null)return Results.NotFound();if(u.IsInRole("Customer")&&a.CustomerId.ToString()!=u.FindFirstValue(ClaimTypes.NameIdentifier))return Results.Forbid();var service=await db.Services.SingleAsync(y=>y.Id==a.ServiceId&&y.TenantId==tenant);if(!(await Slots(db,tenant,a.EmployeeId,service,DateOnly.FromDateTime(x.Starts),id)).Contains(x.Starts))return Results.Conflict(new{error="Слот занят"});a.Starts=x.Starts;a.Ends=x.Starts.AddMinutes(service.DurationMinutes);a.ReminderSent=null;await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(a);});
api.MapPatch("/appointments/{id:guid}",async(Guid id,StatusInput x,ClaimsPrincipal u,BookingDb db)=>{var a=await db.Appointments.SingleOrDefaultAsync(y=>y.Id==id&&y.TenantId==Guid.Parse(u.FindFirstValue("tenant")!));if(a==null)return Results.NotFound();if(u.IsInRole("Customer")&&(a.CustomerId.ToString()!=u.FindFirstValue(ClaimTypes.NameIdentifier)||x.Status!="cancelled")||!new[]{"confirmed","completed","cancelled","no_show"}.Contains(x.Status))return Results.Forbid();a.Status=x.Status;await db.SaveChangesAsync();return Results.Ok(a);});
api.MapGet("/customers",(ClaimsPrincipal u,BookingDb db,int? page)=>Staff(u)?db.Customers.Where(x=>x.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)).OrderBy(x=>x.Name).Skip((Math.Clamp(page??1,1,10000)-1)*50).Take(50):db.Customers.Where(x=>x.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)&&x.Id==Guid.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!)));
api.MapPost("/customers",async(CustomerInput x,ClaimsPrincipal u,BookingDb db)=>{if(!Staff(u))return Results.Forbid();var customer=new Customer{TenantId=Guid.Parse(u.FindFirstValue("tenant")!),Name=x.Name,Phone=x.Phone};db.Customers.Add(customer);await db.SaveChangesAsync();return Results.Ok(customer);});
api.MapGet("/analytics",async(ClaimsPrincipal u,BookingDb db)=>{if(!Staff(u))return Results.Forbid();var t=Guid.Parse(u.FindFirstValue("tenant")!);var data=await db.Appointments.Where(x=>x.TenantId==t).GroupBy(x=>x.Status).Select(x=>new{x.Key,Count=x.Count(),Revenue=x.Where(y=>y.Status=="completed").Sum(y=>y.Price)}).ToListAsync();return Results.Ok(data);});
api.MapGet("/analytics/utilization",async(ClaimsPrincipal u,BookingDb db)=>{if(!Staff(u))return Results.Forbid();var tenant=Guid.Parse(u.FindFirstValue("tenant")!);var since=DateTime.UtcNow.Date.AddDays(-30);var employees=await db.Employees.Where(x=>x.TenantId==tenant).ToListAsync();var appointments=await db.Appointments.Where(x=>x.TenantId==tenant&&x.Starts>=since&&x.Status!="cancelled").ToListAsync();return Results.Ok(employees.Select(x=>new{x.Id,x.Name,Appointments=appointments.Count(a=>a.EmployeeId==x.Id),Hours=Math.Round(appointments.Where(a=>a.EmployeeId==x.Id).Sum(a=>(a.Ends-a.Starts).TotalHours),1)}));});
api.MapGet("/export/appointments",async(ClaimsPrincipal u,BookingDb db)=>{if(!Staff(u))return Results.Forbid();var data=await db.Appointments.Where(x=>x.TenantId==Guid.Parse(u.FindFirstValue("tenant")!)).OrderBy(x=>x.Starts).ToListAsync();var csv="id,employee,customer,start,end,status,price\n"+string.Join("\n",data.Select(x=>$"{x.Id},{x.EmployeeId},{x.CustomerId},{x.Starts:o},{x.Ends:o},{x.Status},{x.Price}"));return Results.File(Encoding.UTF8.GetBytes(csv),"text/csv","appointments.csv");});
app.Run();
record Register(string Email,string Password,string Organization,string Slug);record Login(string Email,string Password);record TelegramAuth(string Tenant,string InitData);record MemberInput(string Email,string Password,string Name,string Role);record TenantInput(string Name);record BranchInput(string Name,string Address);record ServiceInput(string Name,decimal Price,int DurationMinutes);record EmployeeInput(string Name,Guid BranchId);record ShiftInput(DayOfWeek Day,TimeOnly Starts,TimeOnly Ends,bool DayOff);record LeaveInput(Guid EmployeeId,DateTime Starts,DateTime Ends);record CustomerInput(string Name,string Phone);record BookingInput(Guid EmployeeId,Guid ServiceId,Guid CustomerId,DateTime Starts);record RescheduleInput(DateTime Starts);record StatusInput(string Status);
public sealed class Reminders(IServiceScopeFactory scopes,IHttpClientFactory clients,IConfiguration config,ILogger<Reminders> log):BackgroundService{protected override async Task ExecuteAsync(CancellationToken token){using var timer=new PeriodicTimer(TimeSpan.FromMinutes(1));do{try{using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<BookingDb>();var now=DateTime.UtcNow;var due=await db.Appointments.Where(x=>x.Status=="confirmed"&&x.ReminderSent==null&&x.Starts>now.AddMinutes(59)&&x.Starts<now.AddMinutes(61)).ToListAsync(token);foreach(var a in due){var c=await db.Customers.SingleAsync(x=>x.Id==a.CustomerId,token);if(c.TelegramId is not null){var bot=config["TELEGRAM_BOT_TOKEN"];if(!string.IsNullOrWhiteSpace(bot)&&!config.GetValue<bool>("DEMO_MODE")){var response=await clients.CreateClient().PostAsync($"https://api.telegram.org/bot{bot}/sendMessage",new FormUrlEncodedContent(new Dictionary<string,string>{{"chat_id",c.TelegramId.ToString()!},{"text",$"Напоминание: ваша запись {a.Starts:dd.MM HH:mm} UTC"}}),token);if(!response.IsSuccessStatusCode)continue;}else log.LogInformation("DEMO уведомление о записи {Appointment}",a.Id);}a.ReminderSent=now;}await db.SaveChangesAsync(token);}catch(Exception ex){log.LogError(ex,"Ошибка отправки напоминаний");}}while(await timer.WaitForNextTickAsync(token));}}
